import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Search Syntax","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/search-syntax.md","filePath":"user-guide/search-syntax.md","lastUpdated":1785993908000}'),r={name:"user-guide/search-syntax.md"};function i(n,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="search-syntax" tabindex="-1">Search Syntax <a class="header-anchor" href="#search-syntax" aria-label="Permalink to &quot;Search Syntax&quot;">​</a></h1><p>Lertaro&#39;s query box supports more than plain typing. Every operator below can be combined with plain fuzzy terms in the same query.</p><h2 id="fuzzy-matching-default" tabindex="-1">Fuzzy matching (default) <a class="header-anchor" href="#fuzzy-matching-default" aria-label="Permalink to &quot;Fuzzy matching (default)&quot;">​</a></h2><p>Type any part of a name and Lertaro finds it as long as the characters occur in order, anywhere in the file/folder name — you don&#39;t need to type a contiguous substring:</p><table tabindex="0"><thead><tr><th>You type</th><th>Matches</th></tr></thead><tbody><tr><td><code>swlst</code></td><td><code>Lertaro.exe</code></td></tr><tr><td><code>report</code></td><td><code>Q3-report-final.docx</code></td></tr></tbody></table><p>Turn this off under <strong>Settings → General → System → Enable fuzzy matching</strong> and a bare term (no operator) instead has to appear as a contiguous substring — <code>abc</code> no longer matches <code>a-b-c</code>. Every operator in the table below keeps working exactly the same either way; the setting only changes what a bare term requires. The <code>&#39;</code> operator flips exactness for one term regardless of the setting, so you can drop a fuzzy word into an otherwise exact query, or an exact word into an otherwise fuzzy one, without changing the setting itself.</p><h2 id="multiple-words" tabindex="-1">Multiple words <a class="header-anchor" href="#multiple-words" aria-label="Permalink to &quot;Multiple words&quot;">​</a></h2><p>Separate words with a space. Each word narrows the result set further — it does <strong>not</strong> require the words to appear in the same order you typed them:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report final</span></span></code></pre></div><p>matches <code>final-Q3-report.docx</code> just as well as <code>Q3-report-final.docx</code>.</p><h2 id="case-sensitivity" tabindex="-1">Case sensitivity <a class="header-anchor" href="#case-sensitivity" aria-label="Permalink to &quot;Case sensitivity&quot;">​</a></h2><ul><li>An <strong>all-lowercase</strong> query is case-insensitive: <code>myfile</code> matches <code>MyFile</code>, <code>MYFILE</code>, etc.</li><li>A query with <strong>any uppercase letter</strong> becomes case-sensitive for that term: <code>MyFile</code> only matches <code>MyFile</code>, not <code>myfile</code>.</li></ul><h2 id="operators" tabindex="-1">Operators <a class="header-anchor" href="#operators" aria-label="Permalink to &quot;Operators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prefix/Suffix</th><th>Example</th><th>Effect</th></tr></thead><tbody><tr><td><em>(none)</em></td><td><code>report</code></td><td>Fuzzy match anywhere in the name (default).</td></tr><tr><td><code>!</code></td><td><code>!temp</code></td><td><strong>Exclude</strong> results whose name contains the exact substring <code>temp</code> (this one is not fuzzy).</td></tr><tr><td><code>&#39;</code></td><td><code>&#39;report</code></td><td><strong>Flips exactness</strong> for this one term — exact substring instead of fuzzy while fuzzy matching is on (the default); back to fuzzy for this term while fuzzy matching is turned off in Settings.</td></tr><tr><td><code>&#39;...&#39;</code></td><td><code>&#39;final report&#39;</code></td><td>Exact match anchored to word boundaries (won&#39;t match inside a larger word).</td></tr><tr><td><code>^</code></td><td><code>^IMG</code></td><td><strong>Prefix</strong> match — the name must start with <code>IMG</code>.</td></tr><tr><td><code>$</code></td><td><code>.pdf$</code></td><td><strong>Suffix</strong> match — the name must end with <code>.pdf</code>.</td></tr><tr><td><code>^...$</code></td><td><code>^readme.md$</code></td><td><strong>Equals</strong> — the whole name must be exactly <code>readme.md</code>. Only when both wrap the <em>same</em> word; on separate words they stay independent prefix and suffix filters.</td></tr><tr><td><code>|</code></td><td><code>report | summary</code></td><td><strong>OR</strong> — match either side of the pipe.</td></tr></tbody></table><p>You can mix these freely, e.g. <code>^IMG !.png$ 2024</code> finds files starting with <code>IMG</code>, from 2024, that are <em>not</em> PNGs.</p><p>For an OR query, every term that actually matches a given result is highlighted in its name — not just whichever term happened to match first — so <code>report | summary</code> highlights both words in a result whose name contains them both.</p><h2 id="pasting-multiple-lines" tabindex="-1">Pasting multiple lines <a class="header-anchor" href="#pasting-multiple-lines" aria-label="Permalink to &quot;Pasting multiple lines&quot;">​</a></h2><p>Paste text containing several lines — e.g. filenames copied one per line from a spreadsheet or text file — and Lertaro automatically folds them into an OR query instead of pasting them as-is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123</span></span>
<span class="line"><span>456</span></span>
<span class="line"><span>678</span></span></code></pre></div><p>pastes as <code>123 | 456 | 678</code>, matching any of the three. Blank lines are skipped. A normal single-line paste is unaffected.</p><h2 id="targeting-a-drive" tabindex="-1">Targeting a drive <a class="header-anchor" href="#targeting-a-drive" aria-label="Permalink to &quot;Targeting a drive&quot;">​</a></h2><p>Start the query with a drive letter followed by a colon to restrict results to that drive, then continue typing your search as normal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d: report</span></span></code></pre></div><p>searches only on the <code>D:</code> drive.</p><p>The space is optional: <code>d:report</code> means the same thing as <code>d: report</code>.</p><h2 id="path-mode" tabindex="-1">Path mode <a class="header-anchor" href="#path-mode" aria-label="Permalink to &quot;Path mode&quot;">​</a></h2><p>If your query contains a path separator (<code>\\</code> or <code>/</code>), Lertaro switches to path mode and matches against full paths instead of just names — useful for jumping straight to a known folder:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Projects\\Lertaro</span></span></code></pre></div><p>A trailing separator (<code>D:\\Projects\\</code>) searches the <em>contents</em> of that exact folder.</p><h2 id="filtering-by-folder-name-and-wildcards-query-tokens" tabindex="-1">Filtering by folder name and wildcards (Query Tokens) <a class="header-anchor" href="#filtering-by-folder-name-and-wildcards-query-tokens" aria-label="Permalink to &quot;Filtering by folder name and wildcards (Query Tokens)&quot;">​</a></h2><p>Lertaro supports chaining query tokens after your primary search keywords (prefixed by <code>:</code> by default or by dedicated token prefixes) to perform secondary filtering on primary search results:</p><ul><li><strong>Wildcard Secondary Filter (<code>:?&lt;wildcard-expression&gt;</code> or <code>?&lt;wildcard-expression&gt;</code>)</strong>: Uses standard Windows wildcard syntax (<code>?</code> for any single character, <code>*</code> for zero or more characters) to filter primary search results. For example, <code>mp4 :?(2026???????????)</code> or <code>mp4 ?(2026???????????)</code> filters files with 2026 and 11-digit timestamp tags. Use <code>|</code> or <code>;</code> to specify multiple OR wildcard conditions (e.g., <code>?(2026*)|*.png</code>).</li><li><strong>Path Match (<code>::&lt;path-expression&gt;</code>)</strong>: Requires result name or ancestor folder to match the specified text (e.g. <code>1080 ::wallpapers</code> or <code>report ::2024</code>).</li><li><strong>Custom Filter Categories (<code>:@&lt;keyword&gt;</code>)</strong>: Applies pre-configured file extension or category rules (e.g. <code>:@doc</code> or <code>:@video</code>).</li></ul><h2 id="when-a-term-describes-the-folder-not-the-file" tabindex="-1">When a term describes the folder, not the file <a class="header-anchor" href="#when-a-term-describes-the-folder-not-the-file" aria-label="Permalink to &quot;When a term describes the folder, not the file&quot;">​</a></h2><p>If matching by file and folder names alone doesn&#39;t fill the results, Lertaro tops them up by additionally letting terms match ancestor folders — no special syntax needed:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d01j dcj</span></span></code></pre></div><p>finds a file named <code>d01j</code> that lives in a folder named (or aliased to) <code>dcj</code>, even though <code>dcj</code> never appears in the file&#39;s own name. This only fills in the rest of a query from the folders above a file — at least one term still has to match the file name itself, and it only runs when an ordinary name-only search has not filled the page. What it finds is appended after those results rather than mixed into them, so it can never displace or reorder a result an ordinary search would already have found. Ancestor folders are matched the same way file names are, so pinyin reaches a Chinese folder name here too.</p><h2 id="bypassing-exclusion-rules-for-one-search" tabindex="-1">Bypassing exclusion rules for one search <a class="header-anchor" href="#bypassing-exclusion-rules-for-one-search" aria-label="Permalink to &quot;Bypassing exclusion rules for one search&quot;">​</a></h2><p>Start a query with <code>*</code> to search past your own <a href="./settings/index-drives.html#exclusion-rules">exclusion rules</a> — <code>ExcludedPaths</code>, ignored globs, and ignored regexes — just for that search, without changing your settings:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*node_modules</span></span></code></pre></div><p>The <code>*</code> itself is stripped before matching, so it&#39;s never treated as part of the search text. This only reveals results that are already indexed; a folder that was <em>never</em> indexed in the first place (an excluded folder on a network or WSL drive) still won&#39;t appear. Hidden/system files stay filtered either way — this only affects your own exclusion-rule configuration. Typing just <code>*</code> with nothing after it yet shows a &quot;keep typing to search&quot; prompt rather than &quot;No Search Results&quot;, since no search has actually run yet.</p><h2 id="result-type-trigger" tabindex="-1">Result type trigger <a class="header-anchor" href="#result-type-trigger" aria-label="Permalink to &quot;Result type trigger&quot;">​</a></h2><p>Optional, and off by default — you assign the character yourself. If you&#39;ve assigned a trigger character to a result type under <strong>Settings → General → Quick Search Window → Result Type Priority</strong>, typing that character as the very first thing in the quick window shows only that type&#39;s results — Applications, Settings, one specific File Filter, a plugin&#39;s own items, or plain Files — hiding every other type:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;vs</span></span></code></pre></div><p>finds &quot;Visual Studio&quot; among Applications only, if <code>;</code> is that type&#39;s configured trigger, regardless of which other type&#39;s results would otherwise have matched the text better. Typing just the trigger character with nothing after it yet shows a prompt naming the type instead of &quot;No Search Results&quot;. History and Favorites are unaffected either way — they always come first, trigger or not. No trigger is configured by default; see <a href="./settings/general.html#quick-search-window">General settings</a> to set one up.</p><h2 id="chinese-filenames-pinyin-aliasing" tabindex="-1">Chinese filenames: pinyin aliasing <a class="header-anchor" href="#chinese-filenames-pinyin-aliasing" aria-label="Permalink to &quot;Chinese filenames: pinyin aliasing&quot;">​</a></h2><p>Filenames containing Chinese characters are automatically searchable by pinyin, with no setup required:</p><ul><li><strong>Full pinyin</strong>: typing <code>chongqing</code> matches a file named <code>重庆</code>.</li><li><strong>Initials</strong>: typing <code>cq</code> also matches <code>重庆</code> (first letter of each syllable).</li><li><strong>Polyphonic characters</strong> (characters with more than one valid pronunciation) generate aliases for each common reading, so whichever pronunciation you think of is likely to match.</li></ul><p>This is handled by a bundled alias plugin — see <strong>Settings → Plugins</strong> if you ever want to check it&#39;s enabled.</p><h2 id="spanish-filenames-accent-aliasing" tabindex="-1">Spanish filenames: accent aliasing <a class="header-anchor" href="#spanish-filenames-accent-aliasing" aria-label="Permalink to &quot;Spanish filenames: accent aliasing&quot;">​</a></h2><p>Filenames containing Spanish accented characters (<code>á</code>, <code>é</code>, <code>í</code>, <code>ó</code>, <code>ú</code>, <code>ü</code>, <code>ñ</code>) are automatically searchable using plain ASCII letters, with no setup required:</p><ul><li><strong>Unaccented ASCII</strong>: typing <code>cancion</code> matches <code>Canción.mp3</code>, <code>nino</code> matches <code>Niño.txt</code>, and <code>ciguena</code> matches <code>Cigüeña.png</code>.</li><li><strong>Full highlighting</strong>: matching characters (including accented characters in the original name) are highlighted accurately.</li></ul><p>This is handled by the bundled <code>SpanishAlias</code> plugin — see <strong>Settings → Plugins</strong> if you want to verify it is enabled.</p><h2 id="favorites-not-custom-aliases" tabindex="-1">Favorites, not custom aliases <a class="header-anchor" href="#favorites-not-custom-aliases" aria-label="Permalink to &quot;Favorites, not custom aliases&quot;">​</a></h2><p>Lertaro does not have a general-purpose &quot;define your own alias/macro&quot; system. The closest equivalent is <a href="./settings/favorites.html">Favorites</a>: pin a folder, file, or URL under a custom display name, and it becomes searchable by that name (shown with a ★ marker in results). If what you actually want is a custom keyword that launches a program, see <a href="./instant-answers.html#custom-commands">Custom Commands</a> instead.</p>`,54)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
